import { FC } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch, useSelector } from 'react-redux';

import { Modal, type ModalProps, Typography } from 'antd';

import { AppDispatch, RootState } from 'app/appStore';

import { closeJoinModal } from '../../model/joinOfferSlice';
import { EJoinStates } from '../../model/types';
import { ProgramRules } from '../../ui/ProgramRules/ProgramRules';
import { SelectSource } from '../../ui/SelectSource/SelectSource';

interface IJoinOfferProps extends ModalProps {}

export const JoinOffer: FC<IJoinOfferProps> = ({ ...props }) => {
	const dispatch = useDispatch<AppDispatch>();
	const { t } = useTranslation();
	const { modalIsOpened, state } = useSelector((state: RootState) => state.joinOfferSlice);
	const title = state === EJoinStates.SOURCES ? t('Select a source') : t('Affiliate program rules');

	return (
		<Modal {...props} open={modalIsOpened} onCancel={() => dispatch(closeJoinModal())} destroyOnHidden footer={null}>
			<Typography.Title level={2}>{title}</Typography.Title>
			<Typography.Paragraph>
				{t(
					'Carefully read the rules of the program. In case of violation of the rules your site can be disconnected from the program.',
				)}
			</Typography.Paragraph>
			{state === EJoinStates.SOURCES ? <SelectSource /> : <ProgramRules />}
		</Modal>
	);
};
