import { FC, HTMLAttributes } from 'react';

import { Typography } from 'antd';
import cn from 'classnames';

import { Country } from 'entities/Offer';
import { COUNTRIES, FlagIcons } from 'shared/consts';

import styles from './CountryList.module.scss';

interface ICountryListProps extends HTMLAttributes<HTMLDivElement> {
	data: Country[] | undefined;
}

export const CountryList: FC<ICountryListProps> = ({ className, data, ...props }) => {
	return (
		<div {...props} className={cn(className, styles.countries)}>
			{data?.map((country) => (
				<div className={styles.country} key={country?.alpha_2}>
					<img
						src={FlagIcons[country.alpha_2 as keyof typeof COUNTRIES]}
						alt={`Flag ${country.alpha_2}`}
						height={'16px'}
						width={'22px'}></img>
					<Typography.Text>{COUNTRIES[country.alpha_2]}</Typography.Text>
				</div>
			))}
		</div>
	);
};
