import { FC, HTMLAttributes, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch, useSelector } from 'react-redux';

import { Typography } from 'antd';
import cn from 'classnames';

import { AppDispatch, RootState } from 'app/appStore';

import { useSourceSelect } from '../../../Filters/hooks/useSourceSelect';
import { LIMIT_OF_SOURCES } from '../../consts/limitOfSources';
import { setInitState, setSelectedSources, setSourceOptions } from '../../model/joinOfferSlice';
import { TSourceOption } from '../../model/types';
import { SourceItem } from '../SourceItem/SourceItem';

import styles from './AddSource.module.scss';

interface IAddSourceProps extends HTMLAttributes<HTMLDivElement> {}

export const AddSource: FC<IAddSourceProps> = ({ className, ...props }) => {
	const dispatch = useDispatch<AppDispatch>();
	const { t } = useTranslation();
	const { offer, specifiedSource, selectedSources, isInitState } = useSelector(
		(state: RootState) => state.joinOfferSlice,
	);
	const { sourceOptions } = useSourceSelect();

	useEffect(() => {
		if (!isInitState || !offer) {
			return;
		}
		dispatch(setInitState(false));
		dispatch(setSourceOptions(sourceOptions as TSourceOption[]));

		if (sourceOptions?.length) {
			dispatch(setSelectedSources([{ value: specifiedSource, options: sourceOptions }]));
		}
	}, [offer, isInitState, specifiedSource, dispatch, sourceOptions]);

	return (
		<div {...props} className={cn(className, styles.content)}>
			{selectedSources?.map((ss, idx) => (
				<SourceItem key={`source_item_${idx}`} source={ss} index={idx} sourcesLength={selectedSources?.length} />
			))}
			{!selectedSources?.length && (
				<Typography.Text type="secondary">
					{t(`You have already applied for this offer with all of your sources.
           Please visit the 'My Sources' page to add more sources`)}
				</Typography.Text>
			)}
			{selectedSources?.length === LIMIT_OF_SOURCES && (
				<Typography.Text type="secondary">{t('Limit of sources per one apply: 7')}</Typography.Text>
			)}
		</div>
	);
};
