import { FC, HTMLAttributes, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch, useSelector } from 'react-redux';

import { Button, Input, Typography } from 'antd';
import cn from 'classnames';

import { AppDispatch, RootState } from 'app/appStore';
import { useOffersJoinCreateMutation } from 'entities/Offer';
import { EGaCategories, EGaEvents, EGaTypes, EMainRoutes } from 'shared/typings';
import { CountryList } from 'shared/ui';
import { sendGaEvent } from 'shared/utils';

import { closeJoinModal, setModalState } from '../../model/joinOfferSlice';
import { EJoinStates } from '../../model/types';
import { TrafficTypeList } from '../../ui/TrafficTypeList/TrafficTypeList';

import styles from './ProgramRules.module.scss';

interface IProgramRulesProps extends HTMLAttributes<HTMLDivElement> {}

export const ProgramRules: FC<IProgramRulesProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const dispatch = useDispatch<AppDispatch>();
	const { selectedSources, offer } = useSelector((state: RootState) => state.joinOfferSlice);
	const [comment, setComment] = useState('');
	const [errorMsg, setErrorMsg] = useState('');
	const [joinOffer, { status: updateStatus, error: joinError }] = useOffersJoinCreateMutation();
	const isEmptySource = !selectedSources?.length || (selectedSources?.length === 1 && !selectedSources[0]?.value);

	const handleJoinClick = () => {
		joinOffer({
			offerJoin: { sources_uuids: selectedSources.map(({ value }) => value as string), comment: comment },
			slug: offer?.slug || '',
		});

		selectedSources?.forEach(() => {
			sendGaEvent(EGaEvents.SEND_JOIN_PROGRAM, {
				event_option1: EGaCategories.CATALOG,
				event_option2: EGaTypes.JOIN_POPUP,
			});
		});
	};

	useEffect(() => {
		if (updateStatus === 'fulfilled') {
			dispatch(closeJoinModal());
			window.location.replace(`/${EMainRoutes.MY_OFFERS}`);
		}
	}, [updateStatus, dispatch]);

	useEffect(() => {
		if (joinError && 'data' in joinError) {
			const errorData = joinError.data as { detail: string };
			setErrorMsg(errorData.detail || '');
		}
	}, [joinError]);

	return (
		<div {...props} className={cn(className, styles.content)}>
			{offer?.offer_rules && <div dangerouslySetInnerHTML={{ __html: offer.offer_rules as string }}></div>}

			{offer?.offer_traffic_types && (
				<div className={styles.box}>
					<Typography.Title level={5}>{t('Allowed types of traffic')}</Typography.Title>
					<TrafficTypeList trafficTypes={offer.offer_traffic_types} />
				</div>
			)}

			{offer?.countries && (
				<div className={styles.box}>
					<Typography.Title level={5}>{t('Regions')}</Typography.Title>
					<Typography.Text type="secondary">{t('Available only in the following regions')}:</Typography.Text>
					<CountryList data={offer.countries} />
				</div>
			)}

			{!isEmptySource && (
				<div>
					<Input.TextArea value={comment} onChange={(e) => setComment(e.target.value)} placeholder={t('Comment')} />
					<Typography.Text type="danger">{errorMsg}</Typography.Text>
				</div>
			)}

			<div className={styles.buttons}>
				<Button onClick={() => dispatch(setModalState(EJoinStates.SOURCES))} size="large">
					{t('Back')}
				</Button>
				<Button type="primary" onClick={handleJoinClick} disabled={isEmptySource} size="large">
					{t('Join')}
				</Button>
			</div>
		</div>
	);
};
