import { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';

import { ISource, useSourcesListQuery } from 'entities/Source';
import { EFilters, SOURSCES_LIMIT } from 'features/Filters';
import { SOURCE_WARNINGS } from 'shared/consts';
import { EDefaultOptions } from 'shared/typings';

import { OfferRead, SourcesRelationsStatusEnum } from '../api/codegen.api';

export const useOfferDetails = (data: OfferRead | OfferRead[] | null | undefined, isMyOffers?: boolean) => {
	const { data: sourceList, isSuccess: isSourceSuccess } = useSourcesListQuery({ limit: SOURSCES_LIMIT });
	const [offerList, setOfferList] = useState([] as OfferRead[]);
	const [updatedOffer, setUpdatedOffer] = useState({} as OfferRead);
	const [searchParams] = useSearchParams();
	const sourceFilterValue = searchParams.getAll(EFilters.SOURCE)?.[0];

	useEffect(() => {
		if (!data) {
			return;
		}
		const isDetailsPage = !Array.isArray(data);
		const offers = !isDetailsPage ? data : [data];
		if (!offers?.length || !isSourceSuccess) {
			return;
		}
		const allSources = sourceList?.results || [];
		const updatedOffers: OfferRead[] = offers.map((offer) => {
			const offerCountries = offer.countries.map(({ alpha_2 }) => alpha_2);
			const offerTrafficTypes = offer.offer_traffic_types
				.filter(({ allowed }) => allowed)
				.map(({ traffic_type }) => traffic_type.slug);
			const sourcesRelOIds = offer.sources_relations.map(({ source }) => source.uuid);
			const sourcesRelStatuses = offer.sources_relations.map(({ status }) => status);
			const sources: ISource[] = allSources
				.filter((source) => !sourcesRelOIds.includes(source.uuid))
				.map((source) => {
					const warnings = [];
					if (!offerCountries.some((oc) => source?.countries?.includes(oc))) {
						warnings.push(SOURCE_WARNINGS.geo);
					}
					if (!offerTrafficTypes.some((ot) => source?.traffic_types?.includes(ot))) {
						warnings.push(SOURCE_WARNINGS.traffic);
					}
					return { ...source, warnings: warnings };
				});

			let sourceStatus =
				sourceFilterValue === EDefaultOptions.ALL
					? SourcesRelationsStatusEnum.Joined
					: offer.sources_relations?.find(({ source }) => sourceFilterValue === source.uuid)?.status ||
						SourcesRelationsStatusEnum.Joined;
			if (
				(sources?.length && sourcesRelStatuses?.length && sources?.length === sourcesRelStatuses?.length) ||
				(isMyOffers && sourcesRelStatuses?.length > 0 && sourceFilterValue === EDefaultOptions.ALL)
			) {
				sourceStatus = sourcesRelStatuses.includes(SourcesRelationsStatusEnum.Joined)
					? SourcesRelationsStatusEnum.Joined
					: sourcesRelStatuses.includes(SourcesRelationsStatusEnum.Verification)
						? SourcesRelationsStatusEnum.Verification
						: SourcesRelationsStatusEnum.Rejected;
			}
			return {
				...offer,
				sources: sources,
				source_status: sourceStatus,
				source_status_counter:
					sourceFilterValue === EDefaultOptions.ALL
						? sourcesRelStatuses?.length > 1
							? sourcesRelStatuses.length
							: null
						: null,
			};
		});
		if (isDetailsPage) {
			setUpdatedOffer(updatedOffers[0]);
		} else {
			setOfferList(updatedOffers);
		}
	}, [sourceList, data, isMyOffers, isSourceSuccess, sourceFilterValue]);

	return {
		offerList,
		updatedOffer,
	};
};
