import { FC, Fragment } from 'react';
import { useDispatch, useSelector } from 'react-redux';

import { Select, Typography } from 'antd';
import cn from 'classnames';

import { AppDispatch, RootState } from 'app/appStore';
import PlusIcon from 'assets/images/icons/plus.svg?react';
import RemoveIcon from 'assets/images/icons/remove.svg?react';
import { ISource, useSourcesListQuery } from 'entities/Source';
import { SOURSCES_LIMIT } from 'features/Filters';

import { LIMIT_OF_SOURCES } from '../../consts/limitOfSources';
import { setNothingToSelect, setSelectedSources, setSourceOptions } from '../../model/joinOfferSlice';
import { TSourceItem, TSourceOption } from '../../model/types';

import styles from './SourceItem.module.scss';

interface ISourceItemProps {
	source: TSourceItem;
	index: number;
	sourcesLength: number | undefined;
}

export const SourceItem: FC<ISourceItemProps> = ({ source, sourcesLength = 0, index, ...props }) => {
	const dispatch = useDispatch<AppDispatch>();
	const { sourceOptions, selectedSources, isNothingToSelect } = useSelector((state: RootState) => state.joinOfferSlice);
	const { data: sourceList } = useSourcesListQuery({ limit: SOURSCES_LIMIT });

	// const originalSources = offer?.sources;

	// TODO: check where to get sources from
	const originalSources = sourceList?.results;
	const setNewSources = (
		sources: TSourceItem[],
		newOptions: TSourceOption[],
		val: string | null,
		isRemove?: boolean,
	) => {
		const newSources = sources.map((selectedSource, idx) => {
			const currentValue = index === idx && !isRemove ? val : selectedSource.value;
			const warnings = ((originalSources?.find((item) => item.uuid === currentValue) || {}) as ISource).warnings;
			return {
				value: currentValue,
				warnings: warnings,
				options: newOptions
					.filter((newOption) => {
						return !newOption.isUnAvailable || newOption.value === currentValue;
					})
					.map(({ value, label }) => ({ value: value, label: label })),
			};
		});
		dispatch(setSelectedSources(newSources));
		dispatch(setNothingToSelect(!newOptions.filter(({ isUnAvailable }) => !isUnAvailable)?.length));
	};
	const handleSourceChange = (selected: string | null) => {
		const val = selected;
		const oldValue = selectedSources[index].value;
		const newOptions = sourceOptions.map((sourceOption) => ({
			...sourceOption,
			isUnAvailable:
				sourceOption.value === val ? true : oldValue === sourceOption.value ? false : sourceOption.isUnAvailable,
		}));
		dispatch(setSourceOptions(newOptions));
		setNewSources(selectedSources, newOptions, val);
	};
	const handleAddSource = () => {
		if (sourcesLength === LIMIT_OF_SOURCES) {
			return;
		}
		const newSource = { value: null, options: sourceOptions.filter((no) => !no.isUnAvailable) };
		dispatch(setSelectedSources([...selectedSources, newSource]));
	};
	const handleRemoveSource = () => {
		const newOptions = sourceOptions.map((so) => ({
			...so,
			isUnAvailable: so.value === source.value ? false : so.isUnAvailable,
		}));
		dispatch(setSourceOptions(newOptions));
		setNewSources(
			selectedSources.filter((item) => item.value !== source.value),
			newOptions,
			null,
			true,
		);
	};
	return (
		<Fragment>
			<div {...props} className={styles.block}>
				<div className={styles.selectWrapper}>
					<Select
						className={styles.select}
						value={source.value}
						options={source.options}
						onChange={handleSourceChange}
					/>
					<button
						className={styles.iconBtn}
						disabled={index === sourcesLength - 1 && (!source.value || isNothingToSelect)}
						onClick={index === sourcesLength - 1 ? handleAddSource : handleRemoveSource}>
						{index === sourcesLength - 1 ? (
							<PlusIcon
								className={cn(styles.iconPlus, {
									[styles.iconPlus_disabled]: !source.value || isNothingToSelect || sourcesLength === LIMIT_OF_SOURCES,
								})}
							/>
						) : (
							<RemoveIcon className={styles.iconRemove} />
						)}
					</button>
				</div>
				<div className={styles.block}>
					{!!source?.warnings?.length &&
						source.warnings.map((warning) => (
							<Typography.Text key={`warning_${warning}_${index}`} type="warning">
								{warning}
							</Typography.Text>
						))}
				</div>
			</div>
		</Fragment>
	);
};
