import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch, useSelector } from 'react-redux';

import { Badge, Button, Space, Tabs, type TabsProps } from 'antd';
import cn from 'classnames';

import { AppDispatch, RootState } from 'app/appStore';

import { closeJoinModal, setModalState } from '../../model/joinOfferSlice';
import { EJoinStates, ESourceTabs } from '../../model/types';
import { AddSource } from '../../ui/AddSources/AddSource';
import { JoinedSourceList } from '../../ui/JoinedSourceList/JoinedSourceList';

import styles from './SelectSource.module.scss';

interface ISelectSourceProps extends HTMLAttributes<HTMLDivElement> {}

export const SelectSource: FC<ISelectSourceProps> = ({ className, ...props }) => {
	const dispatch = useDispatch<AppDispatch>();
	const { t } = useTranslation();
	const { offer } = useSelector((state: RootState) => state.joinOfferSlice);

	const items: TabsProps['items'] = [
		{
			key: ESourceTabs.JOIN,
			label: t('Add sources'),
			children: <AddSource />,
		},
		{
			key: ESourceTabs.LIST,
			label: (
				<Space>
					{t('Joined sources')}
					<Badge count={offer?.sources_relations?.length || 0} />
				</Space>
			),
			children: <JoinedSourceList sources={offer?.sources_relations} />,
		},
	];

	return (
		<div {...props} className={cn(className, styles.content)}>
			{offer?.sources_relations?.length ? (
				<Tabs defaultActiveKey={ESourceTabs.JOIN} items={items} size={'large'} />
			) : (
				<AddSource />
			)}

			<div className={styles.buttons}>
				<Button size="large" onClick={() => dispatch(closeJoinModal())}>
					{t('Cancel')}
				</Button>
				<Button type="primary" size="large" onClick={() => dispatch(setModalState(EJoinStates.RULES))}>
					{t('Read Rules')}
				</Button>
			</div>
		</div>
	);
};
