import { FC, HTMLAttributes } from 'react';

import cn from 'classnames';

import { SourcesRelationsRead } from 'entities/Offer';
import { JoinedSourceCard } from 'entities/Source';

import styles from './JoinedSourceList.module.scss';

interface IJoinedSourcesProps extends HTMLAttributes<HTMLDivElement> {
	sources: SourcesRelationsRead[] | undefined;
	isOfferDetails?: boolean;
}

export const JoinedSourceList: FC<IJoinedSourcesProps> = ({ className, sources, isOfferDetails, ...props }) => {
	return (
		<div {...props} className={cn(className, styles.list, { [styles.list_details]: isOfferDetails })}>
			{sources?.map((source) => (
				<JoinedSourceCard key={source.source?.uuid} source={source} isOfferDetails={isOfferDetails} />
			))}
		</div>
	);
};
