import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Typography } from 'antd';
import cn from 'classnames';

import AllowedLogo from 'assets/images/icons/allowed.svg';
import DisabledLogo from 'assets/images/icons/disabled.svg';
import { OfferTrafficType } from 'entities/Offer';
import { TRAFFICS } from 'shared/consts';

import styles from './TrafficTypeList.module.scss';

interface ITrafficTypeListProps extends HTMLAttributes<HTMLDivElement> {
	trafficTypes: OfferTrafficType[] | undefined;
}

export const TrafficTypeList: FC<ITrafficTypeListProps> = ({ className, trafficTypes, ...props }) => {
	const { t } = useTranslation();

	return (
		<div {...props} className={cn(className, styles.traffics)}>
			{trafficTypes?.map((trafficType) => (
				<div className={styles.traffic} key={trafficType.traffic_type.slug}>
					<Typography.Text type="secondary">{TRAFFICS[trafficType.traffic_type?.slug] || t('Other')}</Typography.Text>
					<div className={styles.status}>
						<img src={trafficType.allowed ? AllowedLogo : DisabledLogo} alt="status" height="24" width="24" />
						<Typography.Text type="secondary">{trafficType.allowed ? t('Allowed') : t('Forbidden')}</Typography.Text>
					</div>
				</div>
			))}
		</div>
	);
};
